<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;color:#172B2A;font-size:11px}h1{color:#102A43}h2{color:#0F766E;border-bottom:1px solid #ddd;padding-bottom:5px}.meta{background:#f2f7f5;padding:12px}.item{padding:7px;border-bottom:1px solid #eee}.badge{font-weight:bold}.footer{margin-top:30px;color:#667085}</style></head><body><h1>VIMMO — État des lieux</h1><div class="meta"><b>Référence :</b> {{ $inspection->reference }} · version {{ $inspection->version }}<br><b>Type :</b> {{ $inspection->type }}<br><b>Date :</b> {{ $inspection->inspection_date->format('d/m/Y') }}<br><b>Bien :</b> {{ $inspection->contract->unit->property->name }} — {{ $inspection->contract->unit->reference }}<br><b>Adresse :</b> {{ $inspection->contract->unit->property->address }}<br><b>Propriétaire :</b> {{ $inspection->contract->owner->name }}<br><b>Locataire :</b> {{ $inspection->contract->tenant->name }}</div><h2>Éléments contrôlés</h2>@foreach($inspection->items as $item)<div class="item"><b>{{ $item->room }} — {{ $item->element }}</b><br><span class="badge">État : {{ $item->condition }}</span>@if($item->comment)<br>{{ $item->comment }}@endif @if($item->anomaly)<br><b>Anomalie signalée</b>@endif</div>@endforeach<h2>Relevés</h2><pre>{{ json_encode($inspection->readings,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE) }}</pre><h2>Clés et équipements</h2><pre>{{ json_encode(['cles'=>$inspection->keys,'equipements'=>$inspection->equipment],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE) }}</pre><h2>Validations</h2>@foreach($inspection->validations as $validation)<div>{{ $validation->user->name }} — {{ $validation->validated_at->format('d/m/Y H:i') }} — {{ $validation->method }}</div>@endforeach<div class="footer">Document généré le {{ now()->format('d/m/Y H:i') }}. Son intégrité est associée à la référence {{ $inspection->reference }}.</div></body></html>
